func:
const REQUIRED = 'FIELD_CONFIRMATION_REQUIRED';
const cpsId = env.get('CPS_ID') || 'cpslai1';
const cpsName = env.get('CPS_NAME') || 'DistributionConveyorStationLAI';
const endpoint = String(env.get('OPCUA_ENDPOINT') || '').trim();
const broker = String(env.get('MQTT_BROKER_HOST') || '').trim();
const fields = msg.payload?.fields || {};
flow.set('cpslai1_mapping', fields);
flow.set('cpslai1_samples', {});
flow.set('cpslai1_seen_commands', {});
const configuredReads = Object.entries(fields).filter(([_, f]) => String(f?.accessMode || '').toUpperCase().includes('READ') && f?.nodeId && f.nodeId !== REQUIRED && f.evidenceStatus !== REQUIRED);
const missingFields = Object.entries(fields).filter(([_, f]) => f?.required && (!f?.nodeId || f.nodeId === REQUIRED || f.evidenceStatus === REQUIRED)).map(([name]) => name);
if (!endpoint) missingFields.unshift('OPCUA_ENDPOINT');
if (!broker) missingFields.unshift('MQTT_BROKER_HOST');
const integrationState = missingFields.length ? 'awaiting_field_configuration' : 'connecting';
flow.set('cpslai1_integration_state', integrationState);
const now = new Date().toISOString();
const base = { cpsId, cpsName, timestamp: now, integrationState, lifecycleState: 'plugged', operationalState: 'offline', availability: 'unavailable' };
const status = { payload: Object.assign({}, base, { missingFields }), topic: 'cpslai1/status', qos: 1, retain: true };
const health = { payload: Object.assign({}, base, { healthState: 'unknown', opcuaConfigured: !!endpoint, fieldConfigurationReady: missingFields.length === 0, missingFields }), topic: 'cpslai1/health', qos: 1, retain: true };
const subscriptions = configuredReads.map(([field, f]) => ({ topic: f.nodeId, payload: Number(f.samplingInterval || 1000), interval: Number(f.samplingInterval || 1000), _field: field, _mapping: f }));
node.status({ fill: missingFields.length ? 'yellow' : 'blue', shape: 'ring', text: integrationState + ' | reads=' + subscriptions.length });
return [status, subscriptions, health];

const mapping = flow.get('cpslai1_mapping') || {};
const field = msg._field || Object.keys(mapping).find((key) => mapping[key]?.nodeId === msg.topic);
if (!field) return [null, null];
const cfg = mapping[field] || {};
const raw = msg.payload?.value?.value ?? msg.payload?.value ?? msg.payload;
const sourceTimestamp = msg.sourceTimestamp ? new Date(msg.sourceTimestamp).toISOString() : null;
const serverTimestamp = msg.serverTimestamp ? new Date(msg.serverTimestamp).toISOString() : null;
const statusCode = String(msg.statusCode?.name || msg.statusCode || 'Unknown');
const valid = /^Good/i.test(statusCode) && raw !== undefined && raw !== null;
const scale = Number.isFinite(Number(cfg.scale)) ? Number(cfg.scale) : 1;
const value = valid && typeof raw === 'number' ? raw * scale : valid ? raw : null;
const now = new Date().toISOString();
const sample = { field, value, unit: cfg.unit ?? null, dataType: cfg.dataType || null, sourceTimestamp, serverTimestamp, statusCode, quality: statusCode, valid, stale: false, receivedAt: now };
const samples = flow.get('cpslai1_samples') || {};
samples[field] = sample;
flow.set('cpslai1_samples', samples);
flow.set('cpslai1_integration_state', valid ? 'connected' : 'degraded');
const payload = { cpsId: 'cpslai1', cpsName: env.get('CPS_NAME') || 'DistributionConveyorStationLAI', timestamp: now, sourceTimestamp, serverTimestamp, statusCode, integrationState: valid ? 'connected' : 'degraded', data: { [field]: sample } };
const data = { topic: 'cpslai1/data', payload, qos: 1, retain: false };
const sensor = { topic: 'cpslai1/sensordata', payload, qos: 1, retain: false };
return [data, sensor];

const samples = flow.get('cpslai1_samples') || {};
const limit = Number(env.get('OPCUA_STALE_AFTER_MS') || 15000);
const nowMs = Date.now();
let stale = false;
for (const sample of Object.values(samples)) {
  const ts = Date.parse(sample.sourceTimestamp || sample.serverTimestamp || sample.receivedAt || '');
  sample.stale = !Number.isFinite(ts) || nowMs - ts > limit;
  if (sample.stale) { sample.valid = false; stale = true; }
}
flow.set('cpslai1_samples', samples);
const prior = flow.get('cpslai1_integration_state') || 'disconnected';
const state = stale ? 'stale_data' : prior;
flow.set('cpslai1_integration_state', state);
const timestamp = new Date().toISOString();
const base = { cpsId: 'cpslai1', cpsName: env.get('CPS_NAME') || 'DistributionConveyorStationLAI', timestamp, integrationState: state, lifecycleState: 'plugged', operationalState: state === 'connected' ? 'connected' : 'offline', availability: state === 'connected' ? 'available' : 'unavailable' };
return [{ topic: 'cpslai1/status', payload: base, qos: 1, retain: true }, { topic: 'cpslai1/health', payload: Object.assign({}, base, { healthState: state === 'connected' ? 'unknown' : 'unknown', staleFields: Object.entries(samples).filter(([_, s]) => s.stale).map(([f]) => f) }), qos: 1, retain: true }];

const text = String(msg.status?.text || '').toLowerCase();
const fill = String(msg.status?.fill || '');
let integrationState = text.includes('connect') && !text.includes('dis') ? 'connected' : text.includes('reconnect') || text.includes('connecting') ? 'connecting' : text.includes('error') || fill === 'red' ? 'error' : 'disconnected';
flow.set('cpslai1_integration_state', integrationState);
const timestamp = new Date().toISOString();
const base = { cpsId: 'cpslai1', cpsName: env.get('CPS_NAME') || 'DistributionConveyorStationLAI', timestamp, integrationState, lifecycleState: 'plugged', operationalState: integrationState === 'connected' ? 'connected' : 'offline', availability: integrationState === 'connected' ? 'available' : 'unavailable', detail: msg.status?.text || null };
return [{ topic: 'cpslai1/status', payload: base, qos: 1, retain: true }, { topic: 'cpslai1/health', payload: Object.assign({}, base, { healthState: 'unknown' }), qos: 1, retain: true }];

const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const command = String(p.command || p.action || '').toLowerCase();
const commandId = typeof p.commandId === 'string' ? p.commandId.trim() : '';
const correlationId = String(p.correlationId || commandId).trim();
const allowed = ['play','stop','maintenance','return','unplug','reset'];
const nodeField = { play:'PlayNodeId', stop:'StopNodeId', maintenance:'MaintenanceNodeId', return:'ReturnNodeId', unplug:'UnplugNodeId', reset:'ResetNodeId' }[command];
const timestamp = new Date().toISOString();
const baseAck = { cpsId:'cpslai1', cpsName:env.get('CPS_NAME') || 'DistributionConveyorStationLAI', command, commandId:commandId || null, correlationId:correlationId || null, timestamp };
function ack(reason, extra) { return { topic:'cpslai1/ack', payload:Object.assign({}, baseAck, {success:false, reason}, extra || {}), qos:1, retain:false }; }
if (!allowed.includes(command)) return [null, ack('UNSUPPORTED_COMMAND')];
if (!commandId) return [null, ack('COMMAND_ID_REQUIRED')];
if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/.test(commandId)) return [null, ack('INVALID_COMMAND_ID')];
const seen = flow.get('cpslai1_seen_commands') || {};
if (seen[commandId]) return [null, ack('DUPLICATE_COMMAND', { firstSeenAt: seen[commandId] })];
seen[commandId] = timestamp;
const keys = Object.keys(seen).sort((a,b) => Date.parse(seen[b]) - Date.parse(seen[a])).slice(0,1000);
flow.set('cpslai1_seen_commands', Object.fromEntries(keys.map(k => [k, seen[k]])));
const mapping = flow.get('cpslai1_mapping') || {};
const cfg = mapping[nodeField];
if (!cfg || !cfg.nodeId || cfg.nodeId === 'FIELD_CONFIRMATION_REQUIRED' || cfg.evidenceStatus === 'FIELD_CONFIRMATION_REQUIRED') return [null, ack('FIELD_CONFIGURATION_REQUIRED', { missingFields:[nodeField] })];
if (!cfg.dataType || cfg.dataType === 'FIELD_CONFIRMATION_REQUIRED') return [null, ack('FIELD_CONFIGURATION_REQUIRED', { missingFields:[nodeField + '.dataType'] })];
if (cfg.writeValue === undefined || cfg.writeValue === null || cfg.writeValue === 'FIELD_CONFIRMATION_REQUIRED') return [null, ack('FIELD_CONFIGURATION_REQUIRED', { missingFields:[nodeField + '.writeValue'] })];
if (String(env.get('ALLOW_OPCUA_WRITES') || 'false').toLowerCase() !== 'true') return [null, ack('OPCUA_WRITES_DISABLED')];
msg.topic = cfg.nodeId;
msg.payload = cfg.writeValue;
msg.datatype = cfg.dataType;
msg._pendingCommand = baseAck;
msg._safetyNotice = 'PLC interlocks and permissions remain authoritative';
return [msg, null];

const pending = msg._pendingCommand || {};
const statusCode = String(msg.statusCode?.name || msg.statusCode || msg.payload?.statusCode || 'Unknown');
const success = /^Good/i.test(statusCode);
msg.topic = 'cpslai1/ack';
msg.qos = 1;
msg.retain = false;
msg.payload = Object.assign({}, pending, { success, reason: success ? 'OPCUA_WRITE_CONFIRMED' : 'OPCUA_WRITE_REJECTED', statusCode, timestamp:new Date().toISOString(), physicalExecutionConfirmed:false, safetyNotice:'PLC interlocks and permissions remain authoritative' });
return msg;

const timestamp = new Date().toISOString();
const base = { cpsId:'cpslai1', cpsName:env.get('CPS_NAME') || 'DistributionConveyorStationLAI', timestamp, integrationState:'error', lifecycleState:'plugged', operationalState:'offline', availability:'unavailable', detail:msg.error?.message || 'adapter_error' };
flow.set('cpslai1_integration_state','error');
return [{topic:'cpslai1/status',payload:base,qos:1,retain:true},{topic:'cpslai1/health',payload:Object.assign({},base,{healthState:'unknown'}),qos:1,retain:true}];
